import operator
import re
import sys

_TOKEN = re.compile(r"\d+|[A-Z]+\d*|<>|<=|>=|[-+*/(),:=<>]")
_CELL = re.compile(r"[A-Z]\d+")
_CMP = {
    "=": operator.eq,
    "<>": operator.ne,
    "<": operator.lt,
    "<=": operator.le,
    ">": operator.gt,
    ">=": operator.ge,
}


class _Err(Exception):
    def __init__(self, code):
        super().__init__(code)
        self.code = code


class _Parser:
    def __init__(self, text):
        self.toks = _TOKEN.findall(re.sub(r"\s+", "", text))
        self.pos = 0

    def peek(self):
        return self.toks[self.pos] if self.pos < len(self.toks) else None

    def take(self):
        tok = self.toks[self.pos]
        self.pos += 1
        return tok

    def expect(self, tok):
        if self.take() != tok:
            raise ValueError("unexpected token")

    def formula(self):
        node = self.term()
        while self.peek() in ("+", "-"):
            op = self.take()
            node = ("bin", op, node, self.term())
        return node

    def term(self):
        node = self.unary()
        while self.peek() in ("*", "/"):
            op = self.take()
            node = ("bin", op, node, self.unary())
        return node

    def unary(self):
        if self.peek() == "-":
            self.take()
            return ("neg", self.unary())
        return self.atom()

    def atom(self):
        tok = self.take()
        if tok.isdigit():
            return ("num", int(tok))
        if tok == "(":
            node = self.formula()
            self.expect(")")
            return node
        if tok == "IF":
            self.expect("(")
            left = self.formula()
            op = self.take()
            right = self.formula()
            self.expect(",")
            then = self.formula()
            self.expect(",")
            other = self.formula()
            self.expect(")")
            return ("if", op, left, right, then, other)
        if tok in ("SUM", "MIN", "MAX"):
            self.expect("(")
            args = [self.argument()]
            while self.peek() == ",":
                self.take()
                args.append(self.argument())
            self.expect(")")
            return ("call", tok, args)
        return ("ref", tok)

    def argument(self):
        if (
            self.peek() is not None
            and _CELL.fullmatch(self.peek())
            and self.pos + 1 < len(self.toks)
            and self.toks[self.pos + 1] == ":"
        ):
            a = self.take()
            self.take()
            b = self.take()
            return ("range", a, b)
        return self.formula()


def _range_names(a, b):
    c1, r1 = ord(a[0]) - 65, int(a[1:])
    c2, r2 = ord(b[0]) - 65, int(b[1:])
    for r in range(min(r1, r2), max(r1, r2) + 1):
        for c in range(min(c1, c2), max(c1, c2) + 1):
            yield chr(65 + c) + str(r)


def _arith(op, a, b):
    if op == "+":
        return a + b
    if op == "-":
        return a - b
    if op == "*":
        return a * b
    if b == 0:
        raise _Err("#DIV/0!")
    q = abs(a) // abs(b)
    return q if (a < 0) == (b < 0) else -q


def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    sys.setrecursionlimit(max(sys.getrecursionlimit(), 100000))

    asts = {}
    for name, content in cells.items():
        text = content.strip()
        if text.startswith("="):
            asts[name] = _Parser(text[1:]).formula()
        else:
            asts[name] = ("num", int(text))

    values = {}
    busy = set()

    def cell(name):
        if name in values:
            return values[name]
        if name in busy:
            return "#CYCLE!"
        busy.add(name)
        try:
            result = ev(asts[name])
        except _Err as e:
            result = e.code
        busy.discard(name)
        values[name] = result
        return result

    def ref(name):
        if name not in asts:
            return 0
        v = cell(name)
        if isinstance(v, str):
            raise _Err(v)
        return v

    def ev(node):
        kind = node[0]
        if kind == "num":
            return node[1]
        if kind == "ref":
            return ref(node[1])
        if kind == "neg":
            return -ev(node[1])
        if kind == "bin":
            a = ev(node[2])
            b = ev(node[3])
            return _arith(node[1], a, b)
        if kind == "if":
            a = ev(node[2])
            b = ev(node[3])
            if _CMP[node[1]](a, b):
                return ev(node[4])
            return ev(node[5])
        # function call
        vals = []
        for arg in node[2]:
            if arg[0] == "range":
                for name in _range_names(arg[1], arg[2]):
                    if name in asts:
                        vals.append(ref(name))
            else:
                vals.append(ev(arg))
        if node[1] == "SUM":
            return sum(vals)
        if not vals:
            return 0
        if node[1] == "MIN":
            return min(vals)
        return max(vals)

    return {name: cell(name) for name in asts}
